"use strict";
const assert=require("node:assert/strict"),fs=require("node:fs"),os=require("node:os"),path=require("node:path"),test=require("node:test"),b=require("../lib/publication/publication-bundle");
test("builds an immutable candidate and rollback pointer without production activation",async t=>{const d=fs.mkdtempSync(path.join(os.tmpdir(),"b30a-"));t.after(()=>fs.rmSync(d,{recursive:true,force:true}));const jsonl=path.join(d,"source.jsonl"),manifest=path.join(d,"source.manifest.json"),out=path.join(d,"bundle");fs.writeFileSync(jsonl,"{}\n");const digest=require("node:crypto").createHash("sha256").update(fs.readFileSync(jsonl)).digest("hex");fs.writeFileSync(manifest,JSON.stringify({schema_version:1,source_database_digest:"a".repeat(64),source_row_count:1,exported_row_count:1,jsonl_sha256:digest,jsonl_size_bytes:3,ordering_contract:"ident ASC, id ASC",export_complete:true,publication_performed:false,reconciliation_safe:false}));const result=await b.buildBundle({sourceJsonl:jsonl,sourceManifest:manifest,outputRoot:out,publicationId:"b30a",generationId:"b30a-b",rollbackGenerationId:"b30a-a",builderCommit:"fixture"});assert.equal(result.resolved.manifest.generation_id,"b30a-b");assert.ok(fs.existsSync(path.join(out,"rollback-current.json")));});
test("generation ids fail closed",()=>{assert.throws(()=>b.validId("../escape"));assert.throws(()=>b.validId("a/b"));assert.throws(()=>b.validId("a\\b"));assert.throws(()=>b.validId(""));assert.throws(()=>b.validId("x".repeat(129)));});
